/** Msg defines the Msg service. */
export interface Msg {
  /**
   * UpdateParams defines a (governance) operation for updating the module
   * parameters. The authority defaults to the x/gov module account.
   */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
  /** UpdateBalance defines an operation for updating the pool balance */
  UpdateBalance(request: MsgUpdateBalance): Promise<MsgUpdateBalanceResponse>;
  /** UpdateNativeBalance defines an operation for updating the pool native asset balance */
  UpdateNativeBalance(request: MsgUpdateNativeBalance): Promise<MsgUpdateNativeBalanceResponse>;
  /** AddChain defines an operation for adding the chain */
  AddChain(request: MsgAddChain): Promise<MsgAddChainResponse>;
  /** AddToken defines an operation for adding the token */
  AddToken(request: MsgAddToken): Promise<MsgAddTokenResponse>;
  /** RemoveChain defines an operation for removing the chain */
  RemoveChain(request: MsgRemoveChain): Promise<MsgRemoveChainResponse>;
  /** RemoveToken defines an operation for removing the token */
  RemoveToken(request: MsgRemoveToken): Promise<MsgRemoveTokenResponse>;
}

